DROP TABLE IF EXISTS `zatca_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `zatca_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `device_id` bigint(20) unsigned DEFAULT NULL,
  `source_type` varchar(40) NOT NULL,
  `source_id` bigint(20) unsigned NOT NULL,
  `uuid` char(36) NOT NULL,
  `icv` bigint(20) unsigned NOT NULL,
  `document_kind` varchar(30) NOT NULL,
  `invoice_type` varchar(20) NOT NULL,
  `previous_invoice_hash` varchar(255) DEFAULT NULL,
  `invoice_hash` varchar(64) NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'prepared',
  `submission_mode` varchar(20) NOT NULL,
  `unsigned_xml` longtext NOT NULL,
  `signed_xml` longtext DEFAULT NULL,
  `cleared_xml` longtext DEFAULT NULL,
  `validation_results` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`validation_results`)),
  `request_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`request_payload`)),
  `response_payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`response_payload`)),
  `attempt_count` int(10) unsigned NOT NULL DEFAULT 0,
  `submitted_at` timestamp NULL DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `next_retry_at` timestamp NULL DEFAULT NULL,
  `last_error` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `zatca_documents_source_type_source_id_unique` (`source_type`,`source_id`),
  UNIQUE KEY `zatca_documents_company_id_icv_unique` (`company_id`,`icv`),
  UNIQUE KEY `zatca_documents_uuid_unique` (`uuid`),
  KEY `zatca_documents_device_id_foreign` (`device_id`),
  KEY `zatca_documents_company_id_status_created_at_index` (`company_id`,`status`,`created_at`),
  CONSTRAINT `zatca_documents_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `zatca_documents_device_id_foreign` FOREIGN KEY (`device_id`) REFERENCES `zatca_devices` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

